  "Checking connection": { es: "Comprobando conexión", fr: "Vérification de la connexion", de: "Verbindung wird geprüft", pt: "Verificando conexão", ru: "Проверка соединения", zh: "正在检查连接", ja: "接続を確認中", ko: "연결 확인 중" },
  "Privacy": { es: "Privacidad", fr: "Confidentialité", de: "Datenschutz", pt: "Privacidade", ru: "Конфиденциальность", zh: "隐私", ja: "プライバシー", ko: "개인정보" },
  "Check-ins stay on this device. Saving and location are off by default.": { es: "Los registros permanecen en este dispositivo. El guardado y la ubicación están desactivados por defecto.", fr: "Les bilans restent sur cet appareil. L'enregistrement et la localisation sont désactivés par défaut.", de: "Check-ins bleiben auf diesem Gerät. Speichern und Standort sind standardmäßig aus.", pt: "Os registros ficam neste dispositivo. O salvamento e a localização estão desativados por padrão.", ru: "Записи остаются на устройстве. Сохранение и местоположение по умолчанию выключены.", zh: "记录保留在本设备上。保存和位置默认关闭。", ja: "記録はこの端末に保存されます。保存と位置情報は初期設定でオフです。", ko: "체크인은 이 기기에 보관됩니다. 저장과 위치는 기본적으로 꺼져 있습니다." },
  "Read the privacy policy": { es: "Leer la política de privacidad", fr: "Lire la politique de confidentialité", de: "Datenschutzerklärung lesen", pt: "Ler a política de privacidade", ru: "Читать политику конфиденциальности", zh: "阅读隐私政策", ja: "プライバシーポリシーを読む", ko: "개인정보 처리방침 읽기" },
